@dataclass
class Options:
    batch: bool = False
    beep: bool = False
    border: bool = False
    with_scrollbar: bool = False
    mouse: bool = False
    color: bool = False
    reverse: bool = False
    compress: bool = False
    no_title: bool = False
    enable_summary_char: bool = False
    line_number: bool = False
    no_help_banner: bool = False
    no_summary: bool = False
    exec_mode: bool = False
    diff_output_only: bool = False
    precise: bool = False
    after_command: Optional[str] = None
    logfile: Optional[str] = None
    logfile_flag: bool = False
    shell_command: str = "sh -c"
    interval: float = 2.0
    interval_raw: str = "2"
    limit: int = 5000
    tab_size: int = 4
    differences: str = "none"
    output: Optional[str] = "output"
    keymaps: List[str] = field(default_factory=list)
    command_args: List[str] = field(default_factory=list)


@dataclass
class RunResult:
    timestamp: str
    command: str
    status: bool
    output: str
    stdout: str
    stderr: str

    def comparable(self) -> Tuple[str, bool, str, str, str]:
        # Timestamps intentionally do not participate in change detection.
        return (self.command, self.status, self.output, self.stdout, self.stderr)

    def to_dict(self) -> dict:
        return {
            "timestamp": self.timestamp,
            "command": self.command,
            "status": self.status,
            "output": self.output,
            "stdout": self.stdout,
            "stderr": self.stderr,
        }


DUMMY_RESULT = RunResult("", "", True, "", "", "")


def print_help() -> None:
    prog = os.path.basename(sys.argv[0]) or "hwatch"
    sys.stdout.write(HELP_TEMPLATE.format(description=DESCRIPTION, prog=prog))


def cli_error(message: str, *, possible: Optional[str] = None, usage: bool = False) -> None:
    sys.stderr.write(f"error: {message}\n")
    if possible is not None:
        sys.stderr.write(f"  [possible values: {possible}]\n")
    sys.stderr.write("\n")
    if usage:
        sys.stderr.write("Usage: hwatch [OPTIONS] [command]...\n\n")
    sys.stderr.write("For more information, try '--help'.\n")
    raise SystemExit(2)


def panic_output_unwrap() -> None:
    # The original currently panics when -o/--output is present without a value.
    sys.stderr.write("\nthread 'main' panicked at src/main.rs:537:65:\n")
    sys.stderr.write("called `Option::unwrap()` on a `None` value\n")
    sys.stderr.write("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
    raise SystemExit(101)


def missing_value(long_spec: str) -> None:
    cli_error(f"a value is required for '{long_spec}' but none was supplied")


def is_numeric_hyphen_value(s: str) -> bool:
    return bool(re.match(r"^-[0-9.]", s))


def parse_float_value(s: str) -> float:
    try:
        # Rust's f64 parser used by the observed program does not accept comma
        # decimals in this build, despite the manual wording.
        if "," in s:
            raise ValueError
        return float(s)
    except Exception:
        cli_error(f"invalid value '{s}' for '--interval <interval>': invalid float literal")


def parse_usize_value(s: str, long_spec: str) -> int:
    if not re.fullmatch(r"[0-9]+", s or ""):
        cli_error(f"invalid value '{s}' for '{long_spec}': invalid digit found in string")
    return int(s, 10)


def validate_difference(s: str) -> str:
    if s not in ("none", "watch", "line", "word"):
        cli_error(
            f"invalid value '{s}' for '--differences [<differences>]'",
            possible="none, watch, line, word",
        )
    return s


def validate_output(s: str) -> str:
    if s not in ("output", "stdout", "stderr"):
        cli_error(
            f"invalid value '{s}' for '--output [<output>]'",
            possible="output, stdout, stderr",
        )
    return s


LONG_FLAGS = {
    "batch": "batch",
    "beep": "beep",
    "border": "border",
    "with-scrollbar": "with_scrollbar",
    "mouse": "mouse",
    "color": "color",
    "reverse": "reverse",
    "compress": "compress",
    "no-title": "no_title",
    "enable-summary-char": "enable_summary_char",
    "line-number": "line_number",
    "no-help-banner": "no_help_banner",
    "no-summary": "no_summary",
    "exec": "exec_mode",
    "diff-output-only": "diff_output_only",
    "precise": "precise",
}

SHORT_FLAGS = {
    "b": "batch",
    "B": "beep",
    "c": "color",
    "r": "reverse",
    "C": "compress",
    "t": "no_title",
    "N": "line_number",
    "x": "exec_mode",
    "O": "diff_output_only",
}

REQ_VALUE = {
    "aftercommand": ("after_command", "--aftercommand <after_command>"),
    "shell": ("shell_command", "--shell <shell_command>"),
    "interval": ("interval", "--interval <interval>"),
    "limit": ("limit", "--limit <limit>"),
    "tab-size": ("tab_size", "--tab-size <tab_size>"),
    "keymap": ("keymap", "--keymap <keymap>"),
}

SHORT_REQ = {
    "A": "aftercommand",
    "s": "shell",
    "n": "interval",
    "L": "limit",
    "K": "keymap",
}

OPTIONAL_VALUE = {
    "logfile": "logfile",
    "differences": "differences",
    "output": "output",
}

SHORT_OPT = {
    "l": "logfile",
    "d": "differences",
    "o": "output",
}


def set_required_option(opts: Options, name: str, value: str) -> None:
    attr, spec = REQ_VALUE[name]
    if name == "interval":
        opts.interval_raw = value
        opts.interval = parse_float_value(value)
    elif name == "limit":
        opts.limit = parse_usize_value(value, spec)
    elif name == "tab-size":
        opts.tab_size = parse_usize_value(value, spec)
    elif name == "keymap":
        opts.keymaps.append(value)
    else:
        setattr(opts, attr, value)


def set_optional_option(opts: Options, name: str, value: Optional[str]) -> None:
    if name == "logfile":
        opts.logfile_flag = True
        opts.logfile = value
    elif name == "differences":
        opts.differences = "watch" if value is None else validate_difference(value)
    elif name == "output":
        opts.output = None if value is None else validate_output(value)


def maybe_get_required(args: List[str], i: int, spec: str, *, numeric_ok: bool = False) -> Tuple[str, int]:
    if i + 1 >= len(args):
        missing_value(spec)
    nxt = args[i + 1]
    if nxt.startswith("-") and not (numeric_ok and is_numeric_hyphen_value(nxt)):
        missing_value(spec)
    return nxt, i + 1


def maybe_get_optional(args: List[str], i: int) -> Tuple[Optional[str], int]:
    if i + 1 < len(args) and not args[i + 1].startswith("-"):
        return args[i + 1], i + 1
    return None, i


def parse_args(argv: List[str]) -> Options:
    # The observed binary prepends HWATCH defaults before CLI arguments.
    env_args: List[str] = []
    env = os.environ.get("HWATCH")
    if env:
        try:
            env_args = shlex.split(env)
        except ValueError:
            env_args = env.split()
    args = env_args + argv
    opts = Options()

    i = 0
    while i < len(args):
        tok = args[i]

        if tok == "--":
            opts.command_args = args[i + 1 :]
            break

        if tok == "-h" or tok == "--help":
            print_help()
            raise SystemExit(0)
        if tok == "-V" or tok == "--version":
            sys.stdout.write(VERSION + "\n")
            raise SystemExit(0)

        if tok.startswith("--") and len(tok) > 2:
            body = tok[2:]
            if "=" in body:
                name, val = body.split("=", 1)
                has_eq = True
            else:
                name, val = body, None
                has_eq = False

            if name == "help":
                print_help(); raise SystemExit(0)
            if name == "version":
                sys.stdout.write(VERSION + "\n"); raise SystemExit(0)
            if name in LONG_FLAGS:
                setattr(opts, LONG_FLAGS[name], True)
                i += 1
                continue
            if name in REQ_VALUE:
                spec = REQ_VALUE[name][1]
                if not has_eq:
                    val, i = maybe_get_required(args, i, spec, numeric_ok=(name in ("interval", "limit", "tab-size")))
                set_required_option(opts, name, val if val is not None else "")
                i += 1
                continue
            if name in OPTIONAL_VALUE:
                if not has_eq:
                    val, i = maybe_get_optional(args, i)
                set_optional_option(opts, name, val)
                i += 1
                continue

            # Unknown option-looking tokens are command text in this CLI.
            opts.command_args = args[i:]
            break

        if tok.startswith("-") and tok != "-" and not is_numeric_hyphen_value(tok):
            cluster = tok[1:]
            # If the cluster cannot be parsed exactly as flags plus (at most)
            # a final value-taking option, the whole token is the command.
            j = 0
            parsed_any = False
            command_token = False
            while j < len(cluster):
                ch = cluster[j]
                if ch == "h":
                    print_help(); raise SystemExit(0)
                if ch == "V":
                    sys.stdout.write(VERSION + "\n"); raise SystemExit(0)
                if ch in SHORT_FLAGS:
                    setattr(opts, SHORT_FLAGS[ch], True)
                    parsed_any = True
                    j += 1
                    continue
                if ch in SHORT_REQ or ch in SHORT_OPT:
                    # Value-taking short options are accepted in clusters only
                    # when they are the last character. Attached values such as
                    # -n1 or -ostderr behaved as command text in observation.
                    if j != len(cluster) - 1:
                        command_token = True
                        break
                    if ch in SHORT_REQ:
                        name = SHORT_REQ[ch]
                        spec = REQ_VALUE[name][1]
                        val, i = maybe_get_required(args, i, spec, numeric_ok=(name in ("interval", "limit", "tab-size")))
                        set_required_option(opts, name, val)
                    else:
                        name = SHORT_OPT[ch]
                        val, i = maybe_get_optional(args, i)
                        set_optional_option(opts, name, val)
                    parsed_any = True
                    j += 1
                    break
                command_token = True
                break

            if command_token or not parsed_any:
                opts.command_args = args[i:]
                break
            i += 1
            continue

        # First non-option starts the command; following switches belong to it.
        opts.command_args = args[i:]
        break

    # Option validation side effects that occur after parsing.
    if opts.output is None:
        panic_output_unwrap()
    return opts


def timestamp_now() -> str:
    now = _dt.datetime.now()
    return now.strftime("%Y-%m-%d %H:%M:%S.") + f"{now.microsecond // 1000:03d}"


def json_line(obj: dict) -> str:
    return json.dumps(obj, ensure_ascii=False, separators=(",", ":"))


def append_json_result(path: str, result: RunResult) -> None:
    with open(path, "a", encoding="utf-8") as f:
        f.write(json_line(result.to_dict()) + "\n")
        f.flush()


def read_last_log_command(path: Optional[str]) -> Optional[str]:
    if not path:
        return None
    try:
        with open(path, "r", encoding="utf-8") as f:
            last = None
            for line in f:
                line = line.strip()
                if not line:
                    continue
                try:
                    obj = json.loads(line)
                except Exception:
                    continue
                cmd = obj.get("command")
                if cmd:
                    last = str(cmd)
            return last
    except FileNotFoundError:
        return None
    except OSError:
        return None


def decode_lossy(b: bytes) -> str:
    return b.decode("utf-8", "replace")


def os_error_text(exc: OSError) -> str:
    if isinstance(exc, FileNotFoundError):
        return "No such file or directory (os error 2)"
    if isinstance(exc, PermissionError):
        return "Permission denied (os error 13)"
    if getattr(exc, "errno", None) is not None:
        return f"{exc.strerror} (os error {exc.errno})"
    return str(exc)


def split_shell_command(shell_command: str, command: str) -> List[str]:
    try:
        parts = shlex.split(shell_command)
    except ValueError:
        parts = shell_command.split()
    replaced = False
    newparts: List[str] = []
    for p in parts:
        if "{COMMAND}" in p:
            newparts.append(p.replace("{COMMAND}", command))
            replaced = True
        else:
            newparts.append(p)
    if not replaced:
        newparts.append(command)
    return newparts


def split_exec_command(command: str) -> List[str]:
    try:
        return shlex.split(command)
    except ValueError:
        # The Rust shell_words crate reports an error; for display purposes the
        # nearest observable behavior is a failed execution with the message.
        return []


def collect_process(argv: List[str]) -> Tuple[bool, str, str, str]:
    if not argv:
        return False, "No such file or directory (os error 2)", "", ""
    try:
        proc = subprocess.Popen(argv, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    except OSError as exc:
        return False, os_error_text(exc), "", ""

    sel = selectors.DefaultSelector()
    stdout_chunks: List[bytes] = []
    stderr_chunks: List[bytes] = []
    combined_chunks: List[bytes] = []

    assert proc.stdout is not None and proc.stderr is not None
    os.set_blocking(proc.stdout.fileno(), False)
    os.set_blocking(proc.stderr.fileno(), False)
    sel.register(proc.stdout, selectors.EVENT_READ, "stdout")
    sel.register(proc.stderr, selectors.EVENT_READ, "stderr")

    while sel.get_map():
        events = sel.select(timeout=0.1)
        if not events and proc.poll() is not None:
            # Drain what remains.
            events = [(key, None) for key in list(sel.get_map().values())]
        for key, _ in events:
            stream = key.fileobj
            name = key.data
            try:
                chunk = os.read(stream.fileno(), 65536)
            except BlockingIOError:
                continue
            if not chunk:
                try:
                    sel.unregister(stream)
                except Exception:
                    pass
                continue
            combined_chunks.append(chunk)
            if name == "stdout":
                stdout_chunks.append(chunk)
            else:
                stderr_chunks.append(chunk)
    rc = proc.wait()
    out_b = b"".join(stdout_chunks)
    err_b = b"".join(stderr_chunks)
    comb_b = b"".join(combined_chunks)
    return rc == 0, decode_lossy(comb_b), decode_lossy(out_b), decode_lossy(err_b)


def run_command(command: str, opts: Options) -> RunResult:
    if opts.exec_mode:
        argv = split_exec_command(command)
    else:
        argv = split_shell_command(opts.shell_command, command)
    status, combined, out, err = collect_process(argv)
    return RunResult(timestamp_now(), command, status, combined, out, err)


def selected_output(result: RunResult, opts: Options) -> str:
    if opts.output == "stdout":
        return result.stdout
    if opts.output == "stderr":
        return result.stderr
    return result.output


def color_line_number_prefix(n: int, width: int, color: str = GREY) -> str:
    s = str(n)
    return " " * (width - len(s)) + f"{color}{s}{RESET}{color} | {RESET}"


def apply_line_numbers(text: str, reverse: bool = False) -> str:
    lines = text.split("\n")
    if not lines:
        lines = [""]
    nums = list(range(1, len(lines) + 1))
    pairs = list(zip(nums, lines))
    if reverse:
        pairs.reverse()
    width = len(str(len(lines)))
    return "".join(color_line_number_prefix(n, width) + line + "\n" for n, line in pairs)


def reverse_text(text: str) -> str:
    return "\n".join(reversed(text.split("\n"))) + "\n"


def format_watch_diff(prev: str, cur: str) -> str:
    res: List[str] = []
    any_inv_line = False
    for idx, ch in enumerate(cur):
        prev_ch = prev[idx] if idx < len(prev) else None
        if ch == "\n":
            if any_inv_line:
                res.append(RESET)
                any_inv_line = False
            res.append("\n")
            continue
        if prev_ch != ch:
            res.append(INV + ch + INV)
            any_inv_line = True
        else:
            res.append(ch)
    if any_inv_line:
        res.append(RESET)
    s = "".join(res)
    if not s.endswith("\n"):
        s += "\n"
    return s


def line_tokens(s: str) -> List[str]:
    return s.splitlines()


def inline_word_diff(old: str, new: str) -> Tuple[str, str]:
    # Simple word-ish highlighter for replace lines. It intentionally favors
    # close visual similarity over reproducing the exact internal algorithm.
    old_words = re.split(r"(\s+)", old)
    new_words = re.split(r"(\s+)", new)
    sm = difflib.SequenceMatcher(None, old_words, new_words)
    old_out: List[str] = []
    new_out: List[str] = []
    for tag, i1, i2, j1, j2 in sm.get_opcodes():
        if tag == "equal":
            old_out.append(RED + "".join(old_words[i1:i2]) + RESET)
            new_out.append(GREEN + "".join(new_words[j1:j2]) + RESET)
        elif tag in ("replace", "delete"):
            part = "".join(old_words[i1:i2])
            if part:
                old_out.append(WORD_DEL + part + RESET)
        if tag in ("replace", "insert"):
            part = "".join(new_words[j1:j2])
            if part:
                new_out.append(WORD_ADD + part + RESET)
    return "".join(old_out) + RED + RESET, "".join(new_out) + GREEN + RESET


def format_line_or_word_diff(prev: str, cur: str, *, word: bool, only: bool) -> str:
    a = line_tokens(prev)
    b = line_tokens(cur)
    sm = difflib.SequenceMatcher(None, a, b)
    lines: List[str] = []
    for tag, i1, i2, j1, j2 in sm.get_opcodes():
        if tag == "equal":
            if not only:
                for line in b[j1:j2]:
                    lines.append("   " + line + "\n")
        elif tag == "delete":
            for line in a[i1:i2]:
                lines.append(f"{RED}-  {RESET}{RED}{line}{RESET}\n")
        elif tag == "insert":
            for line in b[j1:j2]:
                lines.append(f"{GREEN}+  {RESET}{GREEN}{line}{RESET}\n")
        elif tag == "replace":
            old_block = a[i1:i2]
            new_block = b[j1:j2]
            m = max(len(old_block), len(new_block))
            for k in range(m):
                old_line = old_block[k] if k < len(old_block) else None
                new_line = new_block[k] if k < len(new_block) else None
                if old_line is not None and new_line is not None and word:
                    old_fmt, new_fmt = inline_word_diff(old_line, new_line)
                    lines.append(f"{RED}-  {RESET}{old_fmt}\n")
                    lines.append(f"{GREEN}+  {RESET}{new_fmt}\n")
                else:
                    if old_line is not None:
                        lines.append(f"{RED}-  {RESET}{RED}{old_line}{RESET}{RED}{RESET}\n")
                    if new_line is not None:
                        lines.append(f"{GREEN}+  {RESET}{GREEN}{new_line}{RESET}{GREEN}{RESET}\n")
    return "".join(lines)


def add_line_numbers_to_formatted(text: str) -> str:
    raw_lines = text.splitlines()
    if not raw_lines:
        raw_lines = [""]
    width = len(str(len(raw_lines)))
    return "".join(color_line_number_prefix(i, width) + line + "\n" for i, line in enumerate(raw_lines, 1))


def format_display(prev: RunResult, cur: RunResult, opts: Options) -> str:
    prev_text = selected_output(prev, opts)
    cur_text = selected_output(cur, opts)
    mode = opts.differences

    if mode == "watch":
        text = format_watch_diff(prev_text, cur_text)
        if opts.line_number:
            return add_line_numbers_to_formatted(text)
        if opts.reverse:
            return reverse_text(text.rstrip("\n"))
        return text
    if mode in ("line", "word"):
        text = format_line_or_word_diff(prev_text, cur_text, word=(mode == "word"), only=opts.diff_output_only)
        if opts.line_number:
            return add_line_numbers_to_formatted(text)
        if opts.reverse:
            return reverse_text(text.rstrip("\n"))
        return text

    if opts.line_number:
        return apply_line_numbers(cur_text, reverse=opts.reverse)
    if opts.reverse:
        return reverse_text(cur_text)
    return cur_text + "\n"


def header(ts: str) -> str:
    return f"{GREY}=====[{ts}]========================={RESET}\n"


def print_batch_result(prev: RunResult, cur: RunResult, opts: Options) -> None:
    sys.stdout.write(header(cur.timestamp))
    sys.stdout.write(format_display(prev, cur, opts))
    sys.stdout.flush()
    if opts.beep:
        sys.stdout.write("\a\n")
        sys.stdout.flush()


def run_aftercommand(before: RunResult, after: RunResult, opts: Options) -> None:
    if not opts.after_command:
        return
    try:
        argv = shlex.split(opts.after_command)
    except ValueError:
        argv = opts.after_command.split()
    if not argv:
        return
    env = os.environ.copy()
    env["HWATCH_DATA"] = json_line({"before_result": before.to_dict(), "after_result": after.to_dict()})
    try:
        subprocess.run(argv, env=env)
    except OSError as exc:
        # Match the spirit of an unhandled aftercommand failure by surfacing it.
        sys.stderr.write(os_error_text(exc) + "\n")
        sys.stderr.flush()


def interval_for_sleep(opts: Options) -> float:
    if opts.interval >= 0 and opts.interval < 0.001:
        return 0.001
    return opts.interval


def print_negative_interval_panic_forever() -> None:
    sys.stderr.write("\nthread '<unnamed>' panicked at /rustc/ded5c06cf21d2b93bffd5d884aa6e96934ee4234/library/core/src/time.rs:966:23:\n")
    sys.stderr.write("cannot convert float seconds to Duration: value is negative\n")
    sys.stderr.write("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
    sys.stderr.flush()
    while True:
        time.sleep(3600)


def run_batch(command: str, opts: Options) -> int:
    prev = DUMMY_RESULT
    if opts.logfile:
        append_json_result(opts.logfile, DUMMY_RESULT)

    neg_panic_done = False
    while True:
        start = time.monotonic()
        cur = run_command(command, opts)
        if cur.comparable() != prev.comparable():
            if opts.logfile and prev.timestamp:
                append_json_result(opts.logfile, prev)
            print_batch_result(prev, cur, opts)
            before = prev
            prev = cur
            run_aftercommand(before, cur, opts)
        if opts.interval < 0:
            if not neg_panic_done:
                neg_panic_done = True
                print_negative_interval_panic_forever()
        dur = interval_for_sleep(opts)
        if opts.precise:
            dur = max(0.0, dur - (time.monotonic() - start))
        time.sleep(dur)


def non_tty_once(command: str, opts: Options) -> int:
    # The observed non-batch/non-TTY path runs once, suppresses captured output,
    # and returns success regardless of the child status.
    try:
        run_command(command, opts)
    except Exception:
        pass
    # If a logfile path is provided, the original creates it but writes nothing.
    if opts.logfile:
        try:
            open(opts.logfile, "a", encoding="utf-8").close()
        except OSError:
            pass
    return 0


def draw_screen(command: str, opts: Options, prev: RunResult, cur: RunResult, help_mode: bool) -> None:
    sys.stdout.write("\x1b[H\x1b[2J")
    if not opts.no_title:
        msg = "" if opts.no_help_banner else " Display help with h key!"
        sys.stdout.write(f"Every {opts.interval:9.3f}:{command:<35}{msg} {cur.timestamp}\n")
        mode = opts.differences.capitalize() if opts.differences != "none" else "None"
        sys.stdout.write(f"[Number] [Color] [Reverse] [{opts.output.capitalize() if opts.output else 'Output'}] [History] [{mode:<10}]\n")
    sys.stdout.write(selected_output(cur, opts))
    if not selected_output(cur, opts).endswith("\n"):
        sys.stdout.write("\n")
    if help_mode:
        sys.stdout.write("\n┌ [help] ───────────────────────────────────────────────┐\n")
        sys.stdout.write("│ - [up] key : Move up                                  │\n")
        sys.stdout.write("│ - [down] key : Move down                              │\n")
        sys.stdout.write("│ - [h] key : Show/Hide help                            │\n")
        sys.stdout.write("│ - [q] key : Exit hwatch                               │\n")
        sys.stdout.write("└───────────────────────────────────────────────────────┘\n")
    sys.stdout.flush()


def run_tui(command: str, opts: Options) -> int:
    # A compact terminal UI compatible with the documented key basics. The exact
    # ratatui layout is not necessary for batch tests, but this makes pty use sane.
    old = None
    try:
        if sys.stdin.isatty():
            old = termios.tcgetattr(sys.stdin.fileno())
            tty.setcbreak(sys.stdin.fileno())
        sys.stdout.write("\x1b[?25l")
        sys.stdout.flush()
        prev = DUMMY_RESULT
        cur = run_command(command, opts)
        help_mode = False
        last_run = time.monotonic()
        draw_screen(command, opts, prev, cur, help_mode)
        prev = cur
        while True:
            # Keyboard polling.
            import select

            r, _, _ = select.select([sys.stdin], [], [], 0.05) if sys.stdin.isatty() else ([], [], [])
            if r:
                ch = os.read(sys.stdin.fileno(), 32).decode("utf-8", "ignore")
                if "q" in ch:
                    return 0
                if "h" in ch:
                    help_mode = not help_mode
                    draw_screen(command, opts, prev, cur, help_mode)
                if "+" in ch:
                    opts.interval += 0.5
                    draw_screen(command, opts, prev, cur, help_mode)
                if "-" in ch and opts.interval > 0.5:
                    opts.interval -= 0.5
                    draw_screen(command, opts, prev, cur, help_mode)
            if time.monotonic() - last_run >= interval_for_sleep(opts):
                last_run = time.monotonic()
                nxt = run_command(command, opts)
                if nxt.comparable() != cur.comparable():
                    prev, cur = cur, nxt
                    if opts.beep:
                        sys.stdout.write("\a")
                    draw_screen(command, opts, prev, cur, help_mode)
    except KeyboardInterrupt:
        return 0
    finally:
        sys.stdout.write("\x1b[?25h\x1b[0m")
        sys.stdout.flush()
        if old is not None:
            try:
                termios.tcsetattr(sys.stdin.fileno(), termios.TCSADRAIN, old)
            except Exception:
                pass


def resolve_command(opts: Options) -> str:
    if opts.command_args:
        return " ".join(opts.command_args)
    cmd = read_last_log_command(opts.logfile)
    if cmd:
        return cmd
    cli_error("command not specified and logfile is empty.", usage=True)


def main(argv: List[str]) -> int:
    # Let timeout/SIGTERM terminate without Python tracebacks.
    signal.signal(signal.SIGTERM, lambda signum, frame: os._exit(143))
    opts = parse_args(argv)
    command = resolve_command(opts)
    if opts.batch:
        return run_batch(command, opts)
    if not sys.stdout.isatty():
        return non_tty_once(command, opts)
    return run_tui(command, opts)


if __name__ == "__main__":
    try:
        raise SystemExit(main(sys.argv[1:]))
    except BrokenPipeError:
        try:
            sys.stderr.close()
        except Exception:
            pass
        raise SystemExit(1)
