REQ_VALUE = {
    "aftercommand": ("after_command", "--aftercommand <after_command>"),
    "shell": ("shell_command", "--shell <shell_command>"),
    "interval": ("interval", "--interval <interval>"),
    "limit": ("limit", "--limit <limit>"),
    "tab-size": ("tab_size", "--tab-size <tab_size>"),
    "keymap": ("keymap", "--keymap <keymap>"),
}

SHORT_REQ = {
    "A": "aftercommand",
    "s": "shell",
    "n": "interval",
    "L": "limit",
    "K": "keymap",
